#include <cstdio>
#include <cstring>
#define N 300

int main() {
    char d[N];
    std::scanf("%s", d);
    int n = std::strlen(d);
    int i, j;
    int dot = 0;
    int e = 0;
    for (i = 0; i < n; i++) {
        if (d[i] == '.') {
            dot = i;
        }
        if (d[i] == 'e') {
            e = i;
            break;
        }
    }
    char b[4];
    int nb = 0;
    for (j = e + 1; j < n; j++) {
        b[nb] = d[j];
        nb++;
    }
    b[nb] = '\0';
    int xb = 0;
    for (i = 0; i < nb; i++) {
        xb = xb * 10 + b[i] - '0';
    }
    for (i = 0; i < n; i++) {
        if (d[i] == '.') {
            if (e - dot == 2 && d[dot + 1] == '0') {
                break;
            }
        } else if (d[i] == 'e') {
            break;
        } else {
            if (i == dot + xb + 1) {
                std::printf(".");
            }
            std::printf("%c", d[i]);
        }
    }
    int zero = xb - (e - dot - 1);
    if (e - dot == 2 && d[dot + 1] == '0') {
        zero = xb;
    }
    for (i = 0; i < zero; i++) {
        std::printf("0");
    }
    std::printf("\n");
    return 0;
}

